import type { Access, CollectionConfig } from 'payload' 

// ========================================================== 
// ACCESS CONTROL 
// ========================================================== 

const isAdmin: Access = ({ req }) => { 
  return req.user?.role === 'admin' 
} 

const canRead: Access = ({ req }) => { 
  const role = req.user?.role 

  return role === 'admin' || role === 'editor' || role === 'viewer' 
} 

// ========================================================== 
// PAGES COLLECTION 
// ========================================================== 

export const Pages: CollectionConfig = { 
  slug: 'pages', 

  admin: { 
    useAsTitle: 'title', 
    defaultColumns: ['title', 'slug', 'status', 'updatedAt'], 
    description: 'Static pages for AlloyPress.', 
  }, 

  access: { 
    // Admin + Editor + Viewer can view pages 
    read: canRead, 

    // Only Admin can create pages 
    create: isAdmin, 

    // Only Admin can edit pages 
    update: isAdmin, 

    // Only Admin can delete pages 
    delete: isAdmin, 
  }, 

  fields: [ 
    // ======================================================== 
    // TITLE 
    // ======================================================== 

    { 
      name: 'title', 
      type: 'text', 
      required: true, 
      index: true, 
      label: 'Page Title', 
    }, 

    // ======================================================== 
    // SLUG 
    // ======================================================== 

    { 
      name: 'slug', 
      type: 'text', 
      required: true, 
      unique: true, 
      index: true, 
      label: 'Slug', 
      admin: { 
        description: 'URL slug for this page.', 
        placeholder: 'privacy-policy', 
      }, 
    }, 

    // ======================================================== 
    // CONTENT 
    // ======================================================== 

    { 
      name: 'content', 
      type: 'richText', 
      label: 'Page Content', 

      admin: { 
        description: 'Main content of the page.', 
      }, 
    }, 

    // ======================================================== 
    // EXCERPT 
    // ======================================================== 

    { 
      name: 'excerpt', 
      type: 'textarea', 
      label: 'Excerpt', 

      admin: { 
        description: 'Short description or summary of the page.', 
      }, 
    }, 

    // ======================================================== 
    // FEATURED IMAGE 
    // ======================================================== 

    { 
      name: 'featuredImage', 
      type: 'upload', 
      relationTo: 'media', 
      label: 'Featured Image', 
    }, 

    // ======================================================== 
    // STATUS 
    // ======================================================== 

    { 
      name: 'status', 
      type: 'select', 
      required: true, 

      defaultValue: 'draft', 

      options: [ 
        { 
          label: 'Draft', 
          value: 'draft', 
        }, 
        { 
          label: 'Published', 
          value: 'published', 
        }, 
      ], 

      admin: { 
        position: 'sidebar', 
      }, 
    }, 

    // ======================================================== 
    // SEO 
    // ======================================================== 

    { 
      name: 'seo', 
      type: 'group', 
      label: 'SEO', 

      fields: [ 
        { 
          name: 'title', 
          type: 'text', 
          label: 'SEO Title', 
        }, 

        { 
          name: 'description', 
          type: 'textarea', 
          label: 'Meta Description', 
        }, 

        { 
          name: 'canonicalURL', 
          type: 'text', 
          label: 'Canonical URL', 
        }, 

        { 
          name: 'openGraphImage', 
          type: 'upload', 
          relationTo: 'media', 
          label: 'Open Graph Image', 
        }, 
      ], 
    }, 

    // ======================================================== 
    // WORDPRESS MIGRATION 
    // ======================================================== 

    { 
      name: 'legacy', 
      type: 'group', 

      label: 'Migration / Internal', 

      admin: { 
        description: 
          'Original WordPress page information preserved during migration.', 
      }, 

      fields: [ 
        { 
          name: 'wordpressId', 
          type: 'number', 
          unique: true, 
          index: true, 
          label: 'WordPress Page ID', 
        }, 

        { 
          name: 'wordpressSlug', 
          type: 'text', 
          label: 'WordPress Slug', 
        }, 

        { 
          name: 'wordpressAuthorId', 
          type: 'number', 
          label: 'WordPress Author ID', 
        }, 
      ], 
    }, 
  ], 
}pages.ts 
const PAYLOAD_API_URL =
  process.env.PAYLOAD_API_URL ||
  "http://localhost:3001/api"; 

type PayloadFetchOptions = RequestInit & { 
  next?: { 
    revalidate?: number | false; 
    tags?: string[]; 
  }; 
}; 

const DEFAULT_REVALIDATE = 300; 

export async function payloadFetch<T>( 
  path: string, 
  options: PayloadFetchOptions = {}, 
): Promise<T | null> { 
  try { 
    const { 
      next, 
      cache, 
      ...requestOptions 
    } = options; 

    const fetchOptions: RequestInit & { 
      next?: { 
        revalidate?: number | false; 
        tags?: string[]; 
      }; 
    } = { 
      ...requestOptions, 
    }; 

    if (cache) { 
      fetchOptions.cache = cache; 
    } 

    if (cache !== "no-store") { 
      fetchOptions.next = { 
        revalidate: DEFAULT_REVALIDATE, 
        ...next, 
      }; 
    } else if (next?.tags?.length) { 
      fetchOptions.next = { 
        tags: next.tags, 
      }; 
    } 

    const response = await fetch( 
      ${PAYLOAD_API_URL}${path}, 
      fetchOptions, 
    ); 

    if (!response.ok) { 
      console.error( 
        [Payload] ${response.status} ${response.statusText} - ${path}, 
      ); 

      return null; 
    } 

    return (await response.json()) as T; 
  } catch (error) { 
    console.error( 
      [Payload] Request failed - ${path}, 
      error, 
    ); 

    return null; 
  } 
} 

export { PAYLOAD_API_URL }; payload.ts
