function SocialIcon({
  children,
  label,
  href = "#",
}: {
  children: React.ReactNode;
  label: string;
  href?: string;
}) {
  return (
    <a
      href={href}
      className="footer-social"
      aria-label={label}
      rel={href === "#" ? "nofollow" : "noopener noreferrer"}
      target={href === "#" ? undefined : "_blank"}
    >
      {children}
    </a>
  );
}

function FooterColumn({
  title,
  links,
}: {
  title: string;
  links: {
    label: string;
    href: string;
    popular?: boolean;
    external?: boolean;
  }[];
}) {
  return (
    <div className="footer-column">
      <h3>{title}</h3>

      <nav aria-label={title}>
        <ul>
          {links.map((link) => (
            <li key={link.label}>
              {link.external ? (
                <a
                  href={link.href}
                  target="_blank"
                  rel="noopener noreferrer"
                >
                  {link.label}

                  {link.popular && (
                    <span className="footer-popular">Popular</span>
                  )}
                </a>
              ) : (
                <Link href={link.href}>
                  {link.label}

                  {link.popular && (
                    <span className="footer-popular">Popular</span>
                  )}
                </Link>
              )}
            </li>
          ))}
        </ul>
      </nav>
    </div>
  );
}

