                Honest AI tool reviews, comparisons and alternatives-based on hands on testing.
              </p>

              <div className="footer-socials">
                <SocialIcon
                  label="YouTube"
                  href="https://www.youtube.com/@AlloyPress"
                >
                  <FaYoutube aria-hidden="true" />
                </SocialIcon>

                <SocialIcon
                  label="Instagram"
                  href="https://www.instagram.com/alloypressdotcom/"
                >
                  <FaInstagram aria-hidden="true" />
                </SocialIcon>

                <SocialIcon
                  label="X"
                  href="https://x.com/AlloyPress" 
                > 
                  <FaXTwitter aria-hidden="true" /> 
                </SocialIcon> 
              </div> 
            </div> 

            <FooterColumn 
              title="Navigate" 
              links={navigateLinks} 
            /> 

            <FooterColumn 
              title="Top Resources" 
              links={resourceLinks} 
            /> 

            <FooterColumn 
              title="Company" 
              links={[ 
                companyLinks[0], 
                companyLinks[1], 
                companyLinks[2], 
                { 
                  label: "Get Reviewed", 
                  href: "/review-tool", 
                }, 
                companyLinks[3], 
              ]} 
            /> 

            <FooterColumn 
              title="Learn" 
              links={learnLinks} 
            /> 
          </div> 
        </div> 
      </div> 

      <div className="footer-popular-section"> 
        <div className="container"> 
          <div className="footer-popular-grid"> 
            {popularLinks.map((item) => ( 
              <Link 
                href={item.href} 
                key={item.label} 
                className="footer-popular-item" 
              > 
                <span>{item.category}</span> 
                <strong>{item.label}</strong> 
              </Link> 
            ))} 
          </div> 
        </div> 
      </div> 

      <div className="footer-source"> 
        <div className="container"> 
          <Link 
            href="/about" 
            className="footer-source-link" 
          > 
            Set AlloyPress as the preferred source for AI on Google 
          </Link> 
        </div> 
      </div> 

      <div 
        className="footer-brand-wordmark" 
        aria-hidden="true" 
      > 
        ALLOYPRESS 
      </div> 

      <div className="footer-bottom"> 
        <div className="container footer-bottom-inner"> 
          <nav 
            className="footer-legal" 
            aria-label="Legal" 
          > 
            <Link href="/privacy-policy"> 
              Privacy Policy 
            </Link> 

            <Link href="/terms"> 
              Terms and Conditions 
            </Link> 

            <Link href="/do-not-sell"> 
              Do Not Sell My Info 
            </Link> 
          </nav> 

          <p> 
            Copyright © {new Date().getFullYear()} AlloyPress. 
            All rights reserved. 
          </p> 
        </div> 
      </div> 
